import {products,colors,sizes,sizeRows,cases,faqs,getProduct,colorName,defaultConfig,estimate,statusLabels,imageSources} from './data.js';
import {createGarmentPreview} from './garment-preview.js';
import {createWorkflowStore} from './workflow.js';
import {renderAbout,renderGuides,renderMaterials,renderCatalogues,renderCases,renderFAQ,renderCaseModal,renderMaterialModal} from './content-pages.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('ko-KR')+'원';
const icon=(name='arrow')=>`<svg aria-hidden="true" viewBox="0 0 24 24">${({arrow:'<path d="M4 12h15M13 6l6 6-6 6"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0Z"/><path d="M7 10h10M7 14h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 7h18M3 16h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',check:'<path d="m5 12 5 5L20 7"/>',zoom:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M10 7v6M7 10h6"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',chevron:'<path d="m9 5 7 7-7 7"/>'})[name]||''}</svg>`;
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const safeSave=(key,val)=>{try{localStorage.setItem(key,JSON.stringify(val));return true}catch{toast('저장 공간이 부족합니다. 첨부를 줄이거나 현재 사양을 내려받아 주세요.');return false}};
const store=createWorkflowStore({seed:false});
let config={...defaultConfig(),...safeRead('kw:config',{})}, brief=safeRead('kw:brief',[]),preview=null,viewMode='front',chatOpen=false,chatThread=null,inboxId=null,files=[],rendering=false,toastTimer;
let activeFilter='전체';
let fileReadGeneration=0,fileReadPending=false;
for(const obj of [imageSources.products.field.hero,...Object.values(imageSources.products.field.views).map(v=>v.hero)])obj.matte='neutral';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const route=()=>{const [path,q='']=location.hash.replace(/^#\/?/,'').split('?');return {parts:(path||'home').split('/'),params:new URLSearchParams(q)}};
const go=path=>{if(location.hash==='#/'+path)render();else location.hash='/'+path};
const productMedia=(p,cls='')=>p.sprite?`<div role="img" aria-label="${esc(p.ko)} 정면" class="sprite-photo ${cls}" style="background-image:url('assets/field-views.png');background-size:200% 200%;background-position:0 0;width:auto;height:100%;aspect-ratio:3/2;flex:0 0 auto;mix-blend-mode:multiply"></div>`:`<img class="${cls}" src="${p.image}" alt="${esc(p.ko)}" loading="lazy">`;
const colorDots=p=>`<div class="mini-colors" aria-label="${p.colors.length}가지 컬러">${p.colors.map(id=>`<i style="background:${colors.find(c=>c.id===id).hex}"></i>`).join('')}</div>`;
const productCard=p=>`<a class="product-card" href="#/product/${p.id}"><div class="product-visual"><span class="product-code">${p.code} / ${p.tag}</span>${productMedia(p)}<span class="product-open">${icon()}</span></div><div class="product-info"><div><h3>${p.name}</h3><p>${p.ko} · ${p.material}</p></div>${colorDots(p)}</div></a>`;
const pageHead=(label,title,desc='')=>`<div class="wrap"><header class="page-head"><div class="breadcrumb"><a href="#/">Home</a><span>/</span>${label}</div><span class="eyebrow">${label}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</header></div>`;
const shell=(content)=>`<div class="announce">KUSTOM YOUR WEEK. &nbsp; 당신의 일상에 맞춘 한 벌.</div><header class="site-header"><a class="brand" href="#/" aria-label="KUSWEEK 홈">KUSWEE<span>K</span><small>KUSTOM YOUR WEEK</small></a><nav class="main-nav" aria-label="주 메뉴">${[['about','소개'],['products','컬렉션'],['cases','제작 사례'],['guides','가이드'],['materials','소재 · 공정'],['catalogues','카탈로그']].map(([id,label])=>`<a href="#/${id}" class="${route().parts[0]===id?'active':''}">${label}</a>`).join('')}</nav><div class="header-actions"><a class="request-link" href="#/requests">내 요청</a><a href="#/quote">상담·견적</a><a class="bag" href="#/brief" aria-label="디자인 보관함 ${brief.length}개">${icon('bag')}<span class="bag-count">${brief.length}</span></a><button class="menu-toggle" data-action="menu" aria-label="메뉴 열기" aria-expanded="false">${icon('menu')}</button></div></header><main id="main">${content}</main>${footer()}`;
function footer(){return `<footer class="site-footer"><div class="footer-top"><div><a class="brand" href="#/">KUSWEE<span>K</span><small>KUSTOM YOUR WEEK</small></a><p>셔츠를 만드는 기술로, 당신의 일상을 넓힙니다.<br>한성에프엔씨 · KUSWEEK 디지털 쇼룸</p></div><div><strong>EXPLORE</strong><a href="#/products">컬렉션</a><a href="#/studio/utility">나만의 옷 만들기</a><a href="#/cases">제작 사례</a><a href="#/about">브랜드 소개</a></div><div><strong>SUPPORT</strong><a href="#/guides">제작 가이드</a><a href="#/faq">자주 묻는 질문</a><a href="#/quote">상담·견적 요청</a><a href="#/requests">내 요청과 대화</a></div><div><strong>RESOURCES</strong><a href="#/materials">소재와 공정</a><a href="#/catalogues">카탈로그</a><a href="#/supplier">업체 화면 체험 ↗</a><a href="#/privacy">데모 데이터 안내</a></div></div><div class="footer-bottom"><span>© KUSWEEK. CONCEPT SHOWROOM · 2026</span><span>데모의 요청·채팅은 현재 브라우저에 저장됩니다. <a href="#/supplier">업체 화면 체험 ↗</a></span><span><a href="#/privacy">데이터 안내</a></span></div></footer>`}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">KUSWEEK · SOFT UTILITY COLLECTION</span><h1>Your idea.<br><em>Your wear.</em></h1><p>생각 속에 있던 옷이, 당신의 일상으로.<br>한 벌의 가능성을 고르고, 바꾸고, 함께 완성하세요.</p><a class="btn" href="#/studio/utility">나만의 옷 만들기 ${icon()}</a></div><div class="hero-visual"><img class="hero-back" src="assets/khaki.webp" alt="카키 유틸리티 셔츠"><img class="hero-main" src="assets/clay.webp" alt="워시드 클레이 유틸리티 오버셔츠"></div><div class="hero-line">SHIRTMAKING, REIMAGINED.</div><div class="hero-label">UTILITY OVERSHIRT<br>WASHED COTTON / CLAY</div><div class="hero-index">01 — 03 <span>SCROLL TO EXPLORE ↓</span></div></section><div class="ticker"><span>SHIRTMAKING EXPERTISE</span><span>YOUR FIT. YOUR COLOR.</span><span>FROM IDEA TO SAMPLE</span><span>MADE TOGETHER</span></div><section class="section wrap reveal"><div class="intro-grid"><div><span class="eyebrow">THE KUSWEEK WAY</span><h2>잘 만드는 기술에,<br>당신의 생각을 더하다.</h2></div><div><p>옷을 고르는 경험에서, 옷을 함께 만드는 경험으로.<br>셔츠를 만드는 한성에프엔씨의 전문성을 바탕으로 핏, 컬러, 소재와 디테일을 구체화합니다. 선택한 사양은 그대로 제작 상담의 출발점이 됩니다.</p><a class="text-link" href="#/about">우리의 이야기 ${icon()}</a></div></div></section><section class="section wrap" style="padding-top:0"><div class="section-heading reveal"><div><span class="eyebrow">THE COLLECTION</span><h2>어떤 하루를 입을까요.</h2><p>셔츠에서 오버셔츠, 가벼운 아우터까지.</p></div><a class="text-link" href="#/products">모두 보기 ${icon()}</a></div><div class="product-grid reveal">${products.map(productCard).join('')}</div><p class="demo-note">Soft Utility 방향을 시각화한 데모 디자인입니다. 판매 중인 확정 제품이 아닙니다.</p></section><section class="studio-banner"><div class="copy reveal"><span class="eyebrow">YOUR PERSONAL STUDIO</span><h2>고르는 순간,<br>당신의 옷이 됩니다.</h2><p>컬러가 바뀌고, 실루엣이 달라집니다.<br>화면에서 먼저 만나보세요. 마음에 드는 조합을 저장하면, 제작 담당자와 같은 그림을 보며 이야기할 수 있습니다.</p><a class="btn white" href="#/studio/field">디자인 스튜디오 열기 ${icon()}</a></div><div class="blue-stage"><img src="assets/ivory.png" alt="오프화이트 셔츠의 소재와 실루엣" loading="lazy"><span class="floating-tag">01 &nbsp; YOUR COLOR<br><b>Off-white</b></span><span class="floating-tag two">02 &nbsp; YOUR FIT<br><b>Made for your everyday.</b></span></div></section><section class="section wrap reveal"><div class="section-heading"><div><span class="eyebrow">FROM IDEA TO YOUR WARDROBE</span><h2>하나의 생각이 한 벌이 되기까지.</h2></div><a class="text-link" href="#/guides/sample">제작 과정 ${icon()}</a></div><div class="process-list">${[['01','발견하고','가까운 디자인을 찾고, 화면에서 컬러와 핏을 비교합니다.'],['02','구체화하고','용도·수량·디테일을 선택한 디자인과 함께 정리합니다.'],['03','함께 설계하고','제안한 사양을 바탕으로 CAD와 패턴, 소재를 검토합니다.'],['04','한 벌로 완성합니다','샘플을 확인하고 수정 이력을 남겨 제작 사양을 확정합니다.']].map(([n,t,p])=>`<div class="process-item"><span class="step">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><section class="section wrap" style="padding-top:0"><div class="section-heading reveal"><div><span class="eyebrow">MADE FOR YOUR TEAM</span><h2>다른 일상, 다른 가능성.</h2><p>용도에서 시작하는 디자인 제안 예시.</p></div><a class="text-link" href="#/cases">제작 사례 ${icon()}</a></div><div class="cases-grid reveal">${cases.map(c=>`<a class="case-card" href="#/cases/${c.id}"><div class="case-visual"><span class="case-tag">제안 예시 · ${c.type}</span>${productMedia(getProduct(c.product))}</div><h3>${c.title}</h3><p>${c.meta}</p></a>`).join('')}</div></section><section class="cta-section"><span class="eyebrow">LET’S MAKE SOMETHING YOURS</span><h2>아직은 아이디어여도 괜찮습니다.</h2><p>입는 사람과 필요한 순간을 알려주세요. 함께 방향을 찾아갑니다.</p><a class="btn" href="#/quote">제작 상담 시작하기 ${icon()}</a></section>`}
function collection(params){const category=params.get('category')||'전체',query=params.get('q')||'';let list=products.filter(p=>(category==='전체'||p.category===category)&&`${p.name} ${p.ko} ${p.material}`.toLowerCase().includes(query.toLowerCase()));if(params.get('sort')==='price')list.sort((a,b)=>a.base-b.base);return pageHead('COLLECTION','A shirt. And beyond.','우리가 가장 잘 아는 셔츠의 구조에서 시작해, 당신의 일상으로 넓혀갑니다.')+`<div class="wrap catalog-body"><div class="filter-bar"><div class="tabs">${['전체','캐주얼 셔츠','오버셔츠','셔츠 재킷'].map(t=>`<a class="tab ${category===t?'active':''}" href="#/products?category=${encodeURIComponent(t)}">${t}</a>`).join('')}</div><form id="product-search"><input class="search" name="q" value="${esc(query)}" placeholder="디자인 또는 소재 검색" aria-label="컬렉션 검색"></form><select aria-label="컬렉션 정렬" id="product-sort"><option value="default">추천 순</option><option value="price" ${params.get('sort')==='price'?'selected':''}>예시 단가 낮은 순</option></select></div><div class="catalog-count">${list.length} DESIGNS · 모든 제품은 시각화 데모 디자인입니다.</div><div class="product-grid">${list.map(productCard).join('')}</div>${!list.length?'<div class="empty"><h2>검색 결과가 없습니다.</h2><a href="#/products" class="text-link">전체 컬렉션 보기 →</a></div>':''}</div>`}
function productDetail(id){const p=getProduct(id);return `<div class="wrap"><div class="breadcrumb" style="padding-top:30px"><a href="#/products">컬렉션</a> / ${p.ko}</div><div class="detail-layout"><div class="detail-image">${productMedia(p)}</div><div class="detail-info"><span class="eyebrow">${p.code} · ${p.tag}</span><h1>${p.name}</h1><p class="ko">${p.ko}</p><p class="desc">${p.description}</p><div class="feature-list">${p.features.map(f=>`<span>${f}</span>`).join('')}</div><dl class="spec-list"><div><dt>소재 방향</dt><dd>${p.material}</dd></div><div><dt>착용감</dt><dd>${p.weight} / ${p.fit.length>1?'레귤러 · 릴랙스드':'레귤러'}</dd></div><div><dt>컬러</dt><dd>${p.colors.length} COLORWAYS</dd></div><div><dt>개발 방식</dt><dd>기준 디자인 + 맞춤 사양 검토</dd></div></dl><a class="btn blue full" href="#/studio/${p.id}">나만의 ${p.ko} 만들기 ${icon()}</a><div class="actions" style="margin-top:15px"><button class="text-link" data-action="size-guide">사이즈 가이드 ${icon()}</button><a class="text-link" href="#/guides/sample">제작 과정 ${icon()}</a></div><p class="product-detail-foot">이미지는 디자인 방향을 이해하기 위한 데모입니다. 최종 소재·컬러·핏과 제작 가능 조건은 상담 및 샘플 확인 후 확정합니다.</p></div></div></div><section class="cta-section"><h2>이 디자인으로 시작해볼까요.</h2><p>마음에 드는 컬러와 핏을 저장하고, 바꾸고 싶은 부분을 알려주세요.</p><a class="btn" href="#/studio/${p.id}">디자인 구성하기 ${icon()}</a></section>`}
function studio(id){if(config.product!==id){config=defaultConfig(id);viewMode='front'}const p=getProduct(config.product);return `<div class="studio-topbar"><a href="#/products">← 컬렉션</a><strong>DESIGN YOUR KUSWEEK</strong><a href="#/brief">저장한 디자인 ${brief.length}</a></div><div class="studio-layout"><section class="preview-side" aria-label="선택한 의류 미리보기"><div class="preview-title"><span class="eyebrow">${p.code} / PERSONAL STUDIO</span><h2>${p.name}</h2><p id="preview-caption">${colorName(config.color)} · ${config.fit==='relaxed'?'릴랙스드':'레귤러'} 핏</p></div><div class="canvas-wrap"><img class="garment-fallback" src="${p.image}" alt="${p.ko} 기본 이미지"><canvas class="garment-canvas" aria-label="선택한 컬러와 핏의 의류 미리보기"></canvas><div class="logo-overlay" hidden></div></div><div class="preview-tools"><button class="icon-btn" data-action="zoom" aria-label="디테일 확대">${icon('zoom')}</button><button class="icon-btn" data-action="export-preview" aria-label="미리보기 이미지 저장">${icon('download')}</button></div><div class="preview-watermark">IMAGE-BASED PREVIEW<br>색상·핏은 시각 참고용이며 실제 샘플로 확정합니다.</div><div class="view-controls" aria-label="의류 보기 각도">${viewButtons()}</div></section><aside class="option-side" id="options">${studioOptions()}</aside></div>`}
function viewButtons(){return (config.product==='field'?[['front','앞'],['angle','사선'],['side','옆'],['back','뒤'],['detail','디테일']]:[['front','전체 보기'],['detail','디테일']]).map(([v,l])=>`<button data-action="view" data-value="${v}" class="${viewMode===v?'active':''}" aria-pressed="${viewMode===v}">${l}</button>`).join('')}
function studioOptions(){const p=getProduct(config.product);return `<span class="eyebrow">MAKE IT YOURS</span><h1>당신의 취향을 더하세요.</h1><p class="option-description">선택한 디자인은 제작 상담에 그대로 연결됩니다.</p><div class="field"><label for="studio-product">01 &nbsp; 디자인</label><select id="studio-product">${products.map(p=>`<option value="${p.id}" ${p.id===config.product?'selected':''}>${p.ko}</option>`).join('')}</select></div><div class="option-group"><div class="option-title"><b>02 &nbsp; 컬러</b><small>${colorName(config.color)}</small></div><div class="color-options">${p.colors.map(id=>{const c=colors.find(c=>c.id===id);return `<button class="swatch ${id===config.color?'active':''}" style="--swatch:${c.hex}" data-action="option" data-key="color" data-value="${id}" aria-label="${c.name}" aria-pressed="${id===config.color}"><i></i></button>`}).join('')}</div></div><div class="option-group"><div class="option-title"><b>03 &nbsp; 핏</b><button class="link-button" data-action="size-guide">치수 보기</button></div><div class="option-choice">${p.fit.map(id=>`<button class="choice ${id===config.fit?'active':''}" data-action="option" data-key="fit" data-value="${id}" aria-pressed="${id===config.fit}">${id==='regular'?'레귤러':'릴랙스드'}<small>${id==='regular'?'단정하고 자연스러운 핏':'레이어링을 위한 여유'}</small></button>`).join('')}</div><p class="fine-print">${p.fit.length>1?'준비된 두 실루엣의 이미지를 비교합니다.':'이 디자인은 레귤러 핏 미리보기를 제공합니다. 다른 핏은 상담 요청에 남겨주세요.'}</p></div><div class="option-group"><div class="option-title"><b>04 &nbsp; 브랜드 디테일</b><small>위치 시뮬레이션</small></div><div class="option-choice">${[['none','없음'],['embroidery','가슴 자수'],['print','가슴 프린트']].map(([v,l])=>`<button class="choice ${config.logo===v?'active':''}" data-action="option" data-key="logo" data-value="${v}">${l}</button>`).join('')}</div>${config.logo!=='none'?`<div class="field" style="margin-top:17px;margin-bottom:0"><label for="logo-text">미리볼 문구</label><input id="logo-text" maxlength="18" value="${esc(config.logoText)}"><small>제작 크기·위치·표현은 담당자와 검토합니다. 뒤·옆 보기에는 가슴 로고가 표시되지 않습니다.</small></div>`:''}</div><div class="option-group"><div class="option-title"><b>05 &nbsp; 기준 사이즈 · 수량</b></div><div class="fields"><div class="field"><label for="studio-size">기준 사이즈</label><select id="studio-size">${sizes.map(s=>`<option ${config.size===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="studio-quantity">예상 수량</label><div class="quantity-control"><button data-action="qty" data-value="-10" aria-label="수량 10장 줄이기">−</button><input id="studio-quantity" type="number" min="1" max="10000" value="${config.quantity}" aria-label="예상 수량"><button data-action="qty" data-value="10" aria-label="수량 10장 늘리기">+</button></div></div></div><div class="option-title"><small>${p.material} · 긴소매 · 기본 포켓</small></div><p class="demo-note">소재·소매·포켓 변경은 상담 요청에서 별도로 지정할 수 있습니다.</p><div id="studio-pricing">${priceBlock(config)}</div><table class="tiers"><caption class="demo-note" style="text-align:left">시연용 수량별 단가 예시 (기본 사양)</caption><thead><tr><th>1–99장</th><th>100–299장</th><th>300장 이상</th></tr></thead><tbody><tr>${[1,100,300].map(q=>`<td>${money(estimate({...config,quantity:q,logo:'none'}).unit)}</td>`).join('')}</tr></tbody></table></div><div class="option-footer"><button class="btn blue full" data-action="to-quote">이 디자인으로 상담하기 ${icon()}</button><button class="btn light full" data-action="save-design">디자인 보관함에 저장 ${icon('bag')}</button><button class="link-button" data-action="print-estimate">예시 견적서 인쇄 / PDF 저장</button></div>`}
function priceBlock(c){const e=estimate(c);return `<div class="pricing"><div class="price-row"><span>예시 단가</span><span>${money(e.unit)} × ${e.quantity}장</span></div><div class="price-row"><span>공급가</span><span>${money(e.net)}</span></div><div class="price-row"><span>부가세 10%</span><span>${money(e.vat)}</span></div><div class="price-row total"><span>예상 합계</span><span>${money(e.total)}</span></div><p class="demo-note">기능 시연을 위한 예시 금액입니다. 실제 견적·개발비·납기는 업체 검토 후 확정됩니다.</p></div>`}
function configSpecs(c,quantity=c.quantity){const p=getProduct(c.product);return `<dl class="spec-list">${[['디자인',p.ko],['컬러',colorName(c.color)],['핏',c.fit==='relaxed'?'릴랙스드':'레귤러'],['소재',p.material],['브랜드 디테일',c.logo==='none'||!c.logo?'없음':`${c.logo==='print'?'프린트':'자수'} · ${c.logoText||''}`],['기준 사이즈',c.size||'상담 시 협의'],['수량',quantity+'장']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`}
function quote(){const p=getProduct(config.product),saved=safeRead('kw:quote-draft',{});return pageHead('CONSULTATION','좋은 옷은, 좋은 대화에서.','선택한 디자인과 생각을 함께 남겨주세요. 제작을 위한 구체적인 사양으로 이어갑니다.')+`<div class="wrap form-layout"><form id="quote-form"><div class="saved-tip">선택된 디자인: <strong>${p.ko} · ${colorName(config.color)}</strong> <a href="#/studio/${p.id}" style="float:right;text-decoration:underline">변경하기</a></div><section class="form-card"><h2><span>01</span> 어떤 옷을 만들까요?</h2><div class="fields"><div class="field"><label for="purpose">제작 용도 <em>*</em></label><select id="purpose" name="purpose" required><option value="">선택해 주세요</option><option>팀 유니폼</option><option>브랜드 판매용</option><option>행사·프로젝트</option><option>개인 샘플</option><option>기타</option></select></div><div class="field"><label for="quantity">희망 수량 <em>*</em></label><input id="quantity" name="quantity" type="number" min="1" max="10000" value="${config.quantity}" required></div><div class="field"><label for="deadline">희망 납기</label><input id="deadline" name="deadline" type="date" min="${new Date().toLocaleDateString('en-CA')}"><small>제작 가능 일정은 상담에서 확인합니다.</small></div><div class="field"><label for="budget">예산 범위</label><select id="budget" name="budget"><option>상담 후 결정</option><option>장당 3만원 미만</option><option>장당 3–5만원</option><option>장당 5–8만원</option><option>장당 8만원 이상</option></select></div></div><label class="checkbox"><input id="size-tbd" type="checkbox" checked> 사이즈 구성은 상담 후 결정할게요.</label><div id="size-fields" hidden><p class="note">사이즈별 수량 합계가 전체 희망 수량과 같아야 합니다.</p><div class="size-inputs">${sizes.map(s=>`<label>${s}<input type="number" name="size-${s}" min="0" max="10000" value="0"></label>`).join('')}</div><div class="size-total" id="size-total">사이즈 합계: 0장</div></div></section><section class="form-card"><h2><span>02</span> 바꾸고 싶은 부분을 알려주세요.</h2><div class="fields"><div class="field"><label for="fabric-request">소재 요청</label><select id="fabric-request" name="fabricRequest"><option>선택 디자인의 기본 소재</option><option>더 가벼운 소재</option><option>더 탄탄한 소재</option><option>실물 스와치 상담</option><option>직접 입력</option></select><input name="fabricCustom" id="fabric-custom" hidden placeholder="소재명 또는 원하는 촉감" aria-label="소재 직접 입력"></div><div class="field"><label for="sleeve-request">소매 요청</label><select id="sleeve-request" name="sleeveRequest"><option>기본 긴소매</option><option>반소매로 변경 검토</option><option>소매 길이 조정 검토</option></select></div></div><div class="field"><label for="note">상세 요구사항</label><textarea id="note" name="note" maxlength="3000" placeholder="예: 카페 직원 100명이 입을 셔츠입니다. 여유 있는 핏, 왼쪽 가슴에 4cm 자수, 소매는 2cm 짧게 하고 싶어요."></textarea></div><label class="upload">참고 이미지 · 로고 자료 첨부<input id="request-files" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" multiple><span class="demo-note">PNG, JPG, WEBP, PDF · 파일당 500KB · 최대 3개<br>첨부 내용은 이 브라우저에만 보관되며 실제 업체로 전송되지 않습니다.</span></label><div id="file-list" class="file-list"></div></section><section class="form-card"><h2><span>03</span> 함께 이야기할 분을 알려주세요.</h2><div class="fields">${[['company','회사 / 브랜드','text','브랜드 또는 팀 이름'],['name','담당자 이름','text','담당자 이름'],['email','이메일','email','name@example.com'],['phone','연락처','tel','010-0000-0000']].map(([n,l,t,p])=>`<div class="field"><label for="${n}">${l} <em>*</em></label><input id="${n}" name="${n}" type="${t}" required maxlength="100" placeholder="${p}" value="${esc(saved[n]||'')}"></div>`).join('')}</div><label class="checkbox"><input name="demoAck" required type="checkbox"><span>요청과 연락처가 이 브라우저에만 저장되는 <strong>데모</strong>이며 실제 업체에 전송되지 않음을 확인했습니다. <a href="#/privacy" target="_blank" rel="noopener" style="text-decoration:underline">데이터 안내</a></span></label></section><div id="quote-errors" role="alert"></div><div class="actions"><button type="submit" class="btn blue">데모 상담 요청서 만들기 ${icon()}</button><button type="button" class="btn light" data-action="save-draft">임시 저장</button></div><p class="fine-print">제출 후 업체 화면 체험에서 요청서 검토와 답장을 직접 확인할 수 있습니다.</p></form><aside class="summary-card"><h3>선택한 디자인</h3><div class="summary-product"><div class="mini-image">${configMedia(config)}</div><div><b>${p.name}</b><small>${p.code}</small></div></div>${configSpecs(config)}<div id="quote-pricing">${priceBlock(config)}</div><p class="demo-note">디자인, 컬러, 핏과 브랜드 디테일은 요청 시점의 사양으로 저장됩니다.</p><button class="text-link" data-action="print-estimate">예시 견적서 ${icon('download')}</button></aside></div>`}
function requestSuccess(id){const r=store.getRequest(id);if(!r)return missing();return `<div class="wrap"><section class="success"><div class="success-mark">${icon('check')}</div><span class="eyebrow">YOUR IDEA, READY TO SHARE</span><h1>생각이 하나의 요청서가 되었습니다.</h1><p>${esc(r.contact.company)}의 ${getProduct(r.configSnapshot.product).ko} 요청이<br>현재 브라우저의 데모 요청함에 저장되었습니다.</p><p class="fine-print">실제 업체에 전송된 것이 아닙니다. 아래 업체 화면에서 요청서와 답장을 체험해보세요.</p><div class="actions"><a class="btn blue" href="#/requests/${r.id}">요청서와 대화 보기 ${icon()}</a><a class="btn light" href="#/supplier/${r.id}">업체 화면에서 확인 ${icon()}</a></div></section></div>`}
const statusTrack=status=>{const keys=Object.keys(statusLabels),i=keys.indexOf(status);return `<div class="status-track">${keys.map((k,n)=>`<div class="${n<=i?'done':''}">${statusLabels[k]}</div>`).join('')}</div>`};
function requests(id){if(id){const r=store.getRequest(id);if(!r)return missing();const c=r.configSnapshot;return pageHead('MY REQUEST',getProduct(c.product).ko,'선택한 디자인, 요구사항, 대화를 한곳에서 확인합니다.')+`<div class="wrap form-layout"><section><div class="saved-tip">브라우저 로컬 데모 · 실제 업체로 전송되지 않았습니다.</div><span class="badge">${statusLabels[r.status]}</span>${statusTrack(r.status)}<h3 style="font-size:25px;font-weight:500;margin:30px 0 20px">제작 요구사항</h3>${configSpecs(c,r.quantity)}<dl class="spec-list"><div><dt>희망 납기</dt><dd>${esc(r.deadline||'협의')}</dd></div><div><dt>예산</dt><dd>${esc(r.budget||'협의')}</dd></div><div><dt>사이즈 구성</dt><dd>${sizeSummary(r.configSnapshot.sizeBreakdown)}</dd></div></dl><p style="white-space:pre-wrap;font-size:13px;margin:25px 0;color:#647067">${esc(r.contactNote||'추가 요구사항 없음')}</p>${attachmentLinks(r)}<div class="actions"><button class="btn light small" data-action="print-request" data-id="${r.id}">요청서 인쇄 / PDF</button><a class="btn light small" href="#/supplier/${r.id}">업체 화면 체험</a></div><div id="customer-inline">${inlineChat(r.threadId,'customer')}</div></section><aside class="summary-card"><h3>요청 정보</h3><div class="request-preview">${configMedia(c)}</div><span class="demo-note">${esc(r.id)}</span><dl class="spec-list">${[['회사',r.contact.company],['담당자',r.contact.name],['이메일',r.contact.email],['연락처',r.contact.phone],['작성일',date(r.createdAt)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="demo-note">${esc(r.supplierNote||'업체 검토가 시작되면 진행 상태와 대화로 확인할 수 있습니다.')}</p></aside></div>`}const list=store.getState().requests.slice().reverse();return pageHead('MY REQUESTS','만들어가는 이야기.','상담 요청과 제작 진행 상태를 이어서 확인하세요.')+`<div class="wrap request-list">${list.length?list.map(r=>`<article class="request-card"><div><span class="badge">${statusLabels[r.status]}</span><h3>${getProduct(r.configSnapshot.product).ko}</h3><p class="meta">${esc(r.contact.company)} · ${colorName(r.configSnapshot.color)} · ${r.quantity}장 · ${date(r.createdAt)}</p>${statusTrack(r.status)}</div><div class="actions"><a class="btn light" href="#/requests/${r.id}">요청과 대화 보기 ${icon()}</a></div></article>`).join(''):`<div class="empty"><h2>아직 시작하지 않은 이야기.</h2><p>디자인을 고르고 첫 요청서를 만들어보세요.</p><a class="btn" href="#/products">컬렉션 살펴보기 ${icon()}</a></div>`}</div>`}
function sizeSummary(rows){return Array.isArray(rows)&&rows.length?rows.map(s=>`${esc(s.size)} / ${s.quantity}장`).join(', '):'상담 후 결정'}
function attachmentLinks(r){const saved=safeRead('kw:attachments:'+r.id,[]);return r.attachments?.length?`<div class="file-list">${r.attachments.map((a,i)=>`<button class="file-chip" data-action="attachment" data-id="${r.id}" data-index="${i}" ${saved[i]?'':'disabled'}>${icon('download')}${esc(a.name)}</button>`).join('')}</div>`:''}
function briefPage(){return pageHead('DESIGN ARCHIVE','마음에 드는 조합을 모으세요.','디자인을 비교하고, 선택한 사양으로 상담을 시작할 수 있습니다.')+`<div class="wrap request-list">${brief.length?brief.map(b=>{const p=getProduct(b.config.product);return `<article class="brief-row"><div class="mini-image">${configMedia(b.config)}</div><div><span class="eyebrow" style="margin-bottom:10px">${p.code}</span><h3>${p.ko}</h3><p>${colorName(b.config.color)} · ${b.config.fit==='relaxed'?'릴랙스드':'레귤러'} · ${b.config.quantity}장</p><p>${b.config.logo==='none'?'브랜드 디테일 없음':esc(b.config.logoText)+' '+(b.config.logo==='print'?'프린트':'자수')}</p></div><div class="actions"><button class="btn light small" data-action="edit-saved" data-id="${b.id}">이어서 구성</button><button class="btn small blue" data-action="quote-saved" data-id="${b.id}">상담 요청</button><button class="link-button" data-action="remove-saved" data-id="${b.id}">보관함에서 빼기</button></div></article>`}).join(''):`<div class="empty"><h2>당신만의 컬렉션을 시작하세요.</h2><p>디자인 스튜디오에서 조합을 저장하면 여기에 모입니다.</p><a class="btn" href="#/studio/utility">나만의 옷 만들기 ${icon()}</a></div>`}</div>`}
function supplier(id){const list=store.getState().requests.slice().reverse();const r=list.find(r=>r.id===id)||list[0];inboxId=r?.id;return `<div class="supplier-banner"><span><b>업체 화면 체험</b> · 동일 브라우저의 데모 요청함입니다. 실제 담당자 연결이나 외부 전송은 없습니다.</span><a href="#/requests">고객 화면으로 돌아가기 →</a></div>${pageHead('PARTNER WORKSPACE','같은 사양으로, 같은 대화로.','고객의 선택을 검토하고, 패턴·CAD·샘플 단계까지 이력을 연결합니다.')}<div class="wrap"><div class="inbox-layout"><aside class="inbox-list">${list.length?list.map(x=>`<a class="inbox-item ${x.id===r.id?'active':''}" href="#/supplier/${x.id}"><span class="badge">${statusLabels[x.status]}</span><b>${esc(x.contact.company)} · ${getProduct(x.configSnapshot.product).ko}</b><small>${x.quantity}장 · ${date(x.createdAt)}</small></a>`).join(''):'<p class="demo-note">접수된 데모 요청이 없습니다.</p>'}</aside><section class="inbox-main">${r?`<span class="eyebrow">REQUEST · ${esc(r.id.slice(-8).toUpperCase())}</span><div class="request-preview small">${configMedia(r.configSnapshot)}</div><h2>${esc(r.contact.company)}</h2><p class="demo-note" style="margin-top:12px">${esc(r.contact.name)} · ${esc(r.contact.email)} · ${esc(r.contact.phone)}</p><div class="inbox-specs"><div>${configSpecs(r.configSnapshot,r.quantity)}</div><dl class="spec-list"><div><dt>희망 납기</dt><dd>${esc(r.deadline||'협의')}</dd></div><div><dt>예산</dt><dd>${esc(r.budget||'협의')}</dd></div><div><dt>사이즈</dt><dd>${sizeSummary(r.configSnapshot.sizeBreakdown)}</dd></div></dl></div><p style="white-space:pre-wrap;font-size:13px;margin:25px 0">${esc(r.contactNote||'추가 요구사항 없음')}</p>${attachmentLinks(r)}<div class="actions"><button class="btn light small" data-action="print-request" data-id="${r.id}">요청서 인쇄 / PDF</button><button class="btn light small" data-action="download-json" data-id="${r.id}">사양 데이터 저장</button></div><div class="status-select"><label for="supplier-status">진행 단계</label><select id="supplier-status">${Object.entries(statusLabels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn small blue" data-action="update-status" data-id="${r.id}">상태 반영</button></div><div class="field"><label for="supplier-note">검토 메모 · 고객에게도 표시</label><textarea id="supplier-note" maxlength="2000" placeholder="예: 원단 스와치 확인 후 기준 패턴 검토 예정입니다.">${esc(r.supplierNote||'')}</textarea><button class="btn light small" data-action="save-supplier-note" data-id="${r.id}">검토 메모 저장</button></div><div id="supplier-inline">${inlineChat(r.threadId,'supplier')}</div>`:`<div class="empty"><h2>첫 요청을 기다리고 있습니다.</h2><p>고객 화면에서 요청서를 만들면 이곳에 사양이 나타납니다.</p><a href="#/quote" class="btn">데모 요청 만들기 ${icon()}</a></div>`}</section></div></div>`}
function messagesHTML(id,role='customer'){const t=store.getThread(id);if(!t)return '';return t.messages.map(m=>`<div class="message ${m.role==='system'?'system':m.role===role?'mine':''}"><small>${esc(m.senderLabel|| (m.role==='customer'?'고객':'업체 담당자 체험'))}${m.isAutoReply?' · 데모 자동응답':''}</small><div class="bubble">${esc(m.text)}</div><small>${time(m.createdAt)}</small></div>`).join('')}
function inlineChat(id,role){return `<div class="inline-chat" data-thread="${id}" data-role="${role}"><div class="chat-notice"><b>${role==='supplier'?'업체 담당자로 답장하기':'제작 상담'}</b><span>로컬 데모 대화</span></div><div class="messages">${messagesHTML(id,role)}</div><form class="chat-compose" data-thread="${id}" data-role="${role}"><textarea name="message" aria-label="${role==='supplier'?'업체 답장':'상담 메시지'}" placeholder="${role==='supplier'?'고객에게 전달할 답변을 입력하세요.':'궁금한 내용을 남겨주세요.'}" maxlength="2000" required></textarea><button type="submit">${role==='supplier'?'답장':'보내기'}</button></form></div>`}
function date(d){return d?new Date(d).toLocaleDateString('ko-KR'):''}function time(d){return d?new Date(d).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'}):''}
function renderChat(){const root=$('#chat-root');if(!chatOpen){root.innerHTML=`<button class="chat-launch" data-action="open-chat">${icon('chat')} 제작 상담</button>`;return}const draft=root.querySelector('textarea')?.value||'',focused=document.activeElement===root.querySelector('textarea');let s=store.getState(),t=s.threads.find(x=>x.id===chatThread);if(!t){t=s.threads[s.threads.length-1];chatThread=t?.id}root.innerHTML=`<section class="chat-panel" role="region" aria-label="제작 상담 채팅"><header class="chat-header"><div><b>KUSWEEK 제작 상담</b><small>선택한 디자인에서 이어지는 대화</small></div><button data-action="close-chat" aria-label="상담창 닫기">${icon('close')}</button></header><div class="chat-notice">현재 브라우저에만 저장되는 데모입니다. 실제 담당자에게 전송되지 않습니다. 업체 화면에서 직접 답장을 체험할 수 있습니다.</div>${s.threads.length?`<div class="thread-select"><select id="chat-thread" aria-label="상담 대화 선택">${s.threads.map(x=>`<option value="${x.id}" ${x.id===chatThread?'selected':''}>${esc(x.title)}</option>`).join('')}</select><button data-action="new-chat" title="새 상담">+</button></div>`:''}<div class="messages">${t?messagesHTML(t.id):'<div class="demo-note">현재 디자인에 대해 이야기해보세요.<br>첫 메시지를 보내면 데모 대화가 만들어집니다.</div>'}</div><label class="auto-toggle"><input type="checkbox" id="auto-reply" ${s.settings.autoReply?'checked':''}> 데모 자동응답 체험 (실제 담당자 아님)</label><form class="chat-compose" data-thread="${chatThread||''}" data-role="customer"><textarea name="message" aria-label="상담 메시지 입력" placeholder="어떤 옷을 만들고 싶으세요?" maxlength="2000" required>${esc(draft)}</textarea><button type="submit">보내기</button></form></section>`;root.querySelector('.messages').scrollTop=1e6;if(focused){root.querySelector('textarea').focus();root.querySelector('textarea').setSelectionRange(draft.length,draft.length)}}
function privacy(){return pageHead('DEMO & DATA','안심하고 살펴보세요.','이 웹사이트는 KUSWEEK의 디지털 상품 개발과 제안형 수주 경험을 보여주는 데모입니다.')+`<div class="wrap reading"><h2>요청과 대화는 어디로 가나요?</h2><p>현재 브라우저의 저장 공간에만 남습니다. 실제 업체, 이메일, 서버로 전송하지 않습니다. 같은 브라우저의 다른 탭에서는 요청과 답장이 동기화됩니다. 다른 기기에서는 공유되지 않습니다.</p><h2>어떤 자료가 저장되나요?</h2><p>선택한 디자인, 제작 요구사항, 입력한 회사·담당자·연락처, 대화 및 작은 첨부 파일입니다. 기기와 브라우저를 공유한다면 실제 개인정보 대신 예시 정보를 입력하세요.</p><h2>데모의 범위</h2><p>의류 미리보기는 이미지 기반입니다. AI 자동 설계, 실제 CAD 생성, 생산 발주, 결제, 실시간 업체 알림은 연결되지 않았습니다. 금액과 제작 사례는 설명을 위한 예시이며 실제 거래 조건이나 납품 실적을 뜻하지 않습니다.</p><h2>내 데이터</h2><p>브라우저 데이터를 삭제하면 저장한 내용이 사라질 수 있습니다. 삭제 전에 요청서 인쇄 또는 사양 데이터 다운로드를 이용하세요.</p><div class="actions" style="margin-top:25px"><a class="btn light" href="#/requests">내 요청 보기</a><button class="btn light" data-action="reset-dialog">내 데모 데이터 초기화</button></div></div>`}
function missing(){return `<div class="error-page"><span class="eyebrow">PAGE NOT FOUND</span><h1>찾으시는 페이지가 없습니다.</h1><a class="btn" href="#/" style="margin-top:30px">홈으로 돌아가기 ${icon()}</a></div>`}
async function render(){rendering=true;fileReadGeneration++;fileReadPending=false;preview?.dispose();preview=null;files=[];const {parts:[page,id],params}=route();let content='';try{content=({home,about:renderAbout,products:()=>collection(params),product:()=>productDetail(id),studio:()=>studio(id||'utility'),quote,success:()=>requestSuccess(id),requests:()=>requests(id),brief:briefPage,supplier:()=>supplier(id),guides:()=>renderGuides(id),materials:()=>renderMaterials(params.get('category')||'전체'),catalogues:renderCatalogues,cases:()=>renderCases(params.get('category')||'전체'),faq:renderFAQ,privacy})[page]?.()||missing();$('#app').innerHTML=shell(content);document.title=`${({studio:'나만의 옷 만들기',products:'컬렉션',quote:'제작 상담',supplier:'업체 화면 체험',requests:'내 요청'})[page]||'Your idea. Your wear.'} — KUSWEEK`;window.scrollTo(0,0);if(page==='studio')initPreview();if(page==='quote')restoreQuote();if(page==='cases'&&id)openModal(renderCaseModal(id));const obs=new IntersectionObserver(items=>items.forEach(i=>{if(i.isIntersecting){i.target.classList.add('visible');obs.unobserve(i.target)}}),{threshold:.08});$$('.reveal').forEach(el=>obs.observe(el));$$('.inline-chat .messages').forEach(el=>el.scrollTop=1e6);renderChat()}catch(e){console.error(e);$('#app').innerHTML=shell(`<div class="empty"><h2>화면을 불러오지 못했습니다.</h2><p>새로고침 후 다시 확인해주세요.</p><a href="#/">홈으로</a></div>`)}finally{rendering=false}}
function initPreview(){try{preview=createGarmentPreview($('.garment-canvas'),{imageSources,initial:config,duration:320,onReady:()=>{$('.garment-fallback')?.style.setProperty('opacity','0')},onError:()=>toast('미리보기를 불러오지 못했습니다. 기본 이미지를 표시합니다.')});preview.ready.then(()=>syncPreview());}catch(e){console.error(e)}}
function syncPreview(){if(!preview)return;preview.update({...config,view:viewMode==='detail'?'front':viewMode}).then(()=>{if(!$('.garment-canvas'))return;$('.garment-canvas').style.transform=viewMode==='detail'?'scale(1.65) translateY(12%)':'none';$('.garment-canvas').style.transformOrigin='50% 35%';$('.garment-canvas').style.transition='transform .55s cubic-bezier(.2,.7,.2,1)';});const logo=$('.logo-overlay');if(logo){logo.hidden=config.logo==='none'||['back','side'].includes(viewMode);logo.textContent=config.logoText;logo.className='logo-overlay '+config.logo;logo.style.transform=viewMode==='detail'?'scale(1.4) rotate(-3deg)':'rotate(-3deg)';logo.style.top=viewMode==='detail'?'42%':'38%'}if($('#preview-caption'))$('#preview-caption').textContent=`${colorName(config.color)} · ${config.fit==='relaxed'?'릴랙스드':'레귤러'} 핏`;safeSave('kw:config',config)}
function updateOptions(){if($('#options'))$('#options').innerHTML=studioOptions();syncPreview()}
function openModal(body){const d=$('#modal');d.innerHTML=body.includes('content-modal-title')?body:`<header class="modal-header"><h2>상세 정보</h2><button data-action="close-modal" aria-label="닫기">${icon('close')}</button></header><div class="modal-body">${body}</div>`;if(!d.open)d.showModal()}
function sizeModal(){openModal(`<span class="eyebrow">SIZE REFERENCE</span><h3>일반핏 셔츠 참고 치수</h3><p>제공된 셔츠 사이즈표 기준 · 단위 cm<br>신체 치수가 아닌 의류 실측입니다. 데모 제품별 완성 치수는 샘플 단계에서 확정합니다.</p><div class="table-wrap" style="margin:22px 0"><table><thead><tr><th>사이즈</th>${sizes.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${sizeRows.map(r=>`<tr>${r.map((v,i)=>i?`<td>${v}</td>`:`<th>${v}</th>`).join('')}</tr>`).join('')}</tbody></table></div><a class="btn light" href="downloads/size-guide.pdf" download>전체 사이즈 가이드 PDF ${icon('download')}</a>`)}
function saveDesign(){const same=brief.find(b=>JSON.stringify(b.config)===JSON.stringify(config));if(same){toast('이미 저장된 조합입니다. 보관함에서 확인하세요.');return}brief.push({id:crypto.randomUUID(),config:{...config},createdAt:new Date().toISOString()});if(!safeSave('kw:brief',brief))brief.pop();else{toast('디자인 보관함에 저장했습니다.');$$('.bag-count').forEach(x=>x.textContent=brief.length)}}
function previewKey(c){return JSON.stringify([c.product,c.color,c.fit,c.logo,c.logoText])}
function configMedia(c){return c.previewImage&&c.previewKey===previewKey(c)?`<img src="${esc(c.previewImage)}" alt="${esc(getProduct(c.product).ko+' '+colorName(c.color)+' 선택 사양')}">`:productMedia(getProduct(c.product))}
async function captureConfigPreview(){if(!preview)return;const key=previewKey(config),blob=await preview.exportPng({width:320,height:400});if(blob.size>250*1024)return;const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)});if(key===previewKey(config)){config.previewImage=data;config.previewKey=key;safeSave('kw:config',config)}}
function restoreQuote(){const saved=safeRead('kw:quote-draft',{});for(const [name,value]of Object.entries(saved)){const el=[...$('#quote-form').elements].find(x=>x.name===name);if(el&&el.type!=='checkbox'&&el.type!=='file')el.value=value}$('#size-tbd').checked=saved.sizeTbd!==false;$('#size-fields').hidden=$('#size-tbd').checked;const total=$$('#size-fields input').reduce((sum,el)=>sum+Number(el.value||0),0);$('#size-total').textContent='사이즈 합계: '+total+'장 / 희망 수량 '+$('#quantity').value+'장';$('#quote-pricing').innerHTML=priceBlock({...config,quantity:Number($('#quantity').value)||config.quantity});const d=$('#deadline');if(d)d.min=new Date().toISOString().slice(0,10);if($('#fabric-request')?.value==='직접 입력')$('#fabric-custom').hidden=false}
function quoteDraft(){const f=$('#quote-form');if(!f)return;return {...Object.fromEntries([...new FormData(f)].filter(([key,value])=>key!=='demoAck'&&typeof value==='string')),sizeTbd:$('#size-tbd').checked}}
function updateFileReadUI(loading){fileReadPending=loading;const submit=$('#quote-form button[type="submit"]');if(submit){submit.disabled=loading;submit.setAttribute('aria-busy',String(loading))}const list=$('#file-list');if(list){list.setAttribute('aria-live','polite');list.setAttribute('aria-busy',String(loading));list.innerHTML=loading?'<span class="demo-note">참고 자료를 읽고 있습니다. 완료 후 제출할 수 있습니다.</span>':files.map((f,i)=>`<span class="file-chip">${esc(f.name)} <button type="button" data-action="remove-file" data-index="${i}" aria-label="${esc(f.name)} 제거">×</button></span>`).join('')}}
async function handleFiles(list){const generation=++fileReadGeneration;updateFileReadUI(false);const selected=[...list];if(selected.length>3){toast('첨부는 최대 3개입니다.');$('#request-files').value='';return}const allowed=['image/png','image/jpeg','image/webp','application/pdf'];if(selected.some(f=>f.size>500*1024||!allowed.includes(f.type))){toast('PNG, JPG, WEBP, PDF 파일을 500KB 이하로 첨부해 주세요.');$('#request-files').value='';return}updateFileReadUI(true);try{const nextFiles=await Promise.all(selected.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,size:f.size,type:f.type,lastModified:f.lastModified,data:reader.result});reader.onerror=()=>reject(reader.error||new Error('첨부 파일 읽기 실패'));reader.onabort=()=>reject(new Error('첨부 파일 읽기 취소'));reader.readAsDataURL(f)})));if(generation!==fileReadGeneration||!$('#request-files'))return;files=nextFiles}catch(error){if(generation===fileReadGeneration&&$('#request-files'))toast('파일을 읽지 못했습니다. 다시 선택해 주세요.')}finally{if(generation===fileReadGeneration&&$('#request-files'))updateFileReadUI(false)}}
async function submitQuote(form){if(fileReadPending){toast('첨부 자료를 모두 읽은 후 제출해 주세요.');return}const data=new FormData(form),quantity=Number(data.get('quantity')),sizeBreakdown=$('#size-tbd').checked?[]:sizes.map(s=>({size:s,quantity:Number(data.get('size-'+s)||0)}));let errs=[];if(!Number.isInteger(quantity)||quantity<1||quantity>10000)errs.push('수량은 1–10,000장의 정수로 입력해 주세요.');if(sizeBreakdown.length&&sizeBreakdown.reduce((a,x)=>a+x.quantity,0)!==quantity)errs.push('사이즈별 수량 합계를 전체 수량과 맞춰주세요.');if(data.get('deadline')&&data.get('deadline')<new Date().toISOString().slice(0,10))errs.push('희망 납기는 오늘 이후로 선택해주세요.');if(data.get('fabricRequest')==='직접 입력'&&!String(data.get('fabricCustom')).trim())errs.push('직접 입력할 소재를 적어주세요.');if(errs.length){$('#quote-errors').innerHTML=`<div class="form-error">${errs.map(esc).join('<br>')}</div>`;$('#quote-errors').scrollIntoView({block:'center'});return}const contact=Object.fromEntries(['company','name','email','phone'].map(k=>[k,String(data.get(k)).trim()]));if(Object.values(contact).some(v=>!v)){toast('회사와 담당자 연락처를 확인해 주세요.');return}const note=`용도: ${data.get('purpose')}\n소재: ${data.get('fabricRequest')==='직접 입력'?data.get('fabricCustom'):data.get('fabricRequest')}\n소매: ${data.get('sleeveRequest')}\n\n${String(data.get('note')||'').trim()}`;try{const r=store.createRequest({config:{...config,quantity,purpose:data.get('purpose')},title:contact.company+' · '+getProduct(config.product).ko,quantity,sizeBreakdown,deadline:data.get('deadline'),budget:data.get('budget'),contact,contactNote:note,attachments:files});if(files.length&&!safeSave('kw:attachments:'+r.id,files))toast('요청은 저장됐지만 첨부 내용은 저장 공간 부족으로 보관되지 않았습니다.');safeSave('kw:quote-draft',{});chatThread=r.threadId;go('success/'+r.id)}catch(e){$('#quote-errors').innerHTML=`<div class="form-error">${esc(e.message)}</div>`}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printDocument(c,r){let area=$('.print-area');if(!area){area=document.createElement('section');area.className='print-area';document.body.append(area)}const p=getProduct(c.product),e=estimate(c);area.innerHTML=`<div class="brand">KUSWEEK</div><h1>${r?'제작 상담 요청서':'제작 예시 견적서'}</h1><p>작성일 ${new Date().toLocaleDateString('ko-KR')} · ${r?esc(r.id):'DEMO ESTIMATE'}</p>${c.previewImage?`<img class="print-photo" src="${esc(c.previewImage)}" alt="선택한 의류">`:""}<h2>${p.ko}</h2>${configSpecs(c,r?.quantity||c.quantity)}${r?`<h2>요청 정보</h2><p>${esc(r.contact.company)} / ${esc(r.contact.name)} / ${esc(r.contact.email)} / ${esc(r.contact.phone)}</p><p>희망 납기: ${esc(r.deadline||'협의')} · 예산: ${esc(r.budget||'협의')}</p><p>사이즈: ${sizeSummary(r.configSnapshot.sizeBreakdown)}</p><p style="white-space:pre-wrap">${esc(r.contactNote)}</p>`:`<h2>금액 예시</h2><table><tr><th>단가</th><th>수량</th><th>공급가</th><th>부가세</th><th>합계</th></tr><tr><td>${money(e.unit)}</td><td>${e.quantity}장</td><td>${money(e.net)}</td><td>${money(e.vat)}</td><td>${money(e.total)}</td></tr></table>`}<footer>이 문서는 데모에서 생성되었습니다. 실제 업체에 전송되지 않으며, 실제 견적·납기·제작 조건은 업체와 별도 협의가 필요합니다.<br>이미지 미리보기는 디자인 참고용입니다. 소재·패턴·핏·색상은 실물 샘플 검토 후 확정합니다.</footer>`;window.print()}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,k=el.dataset.key,v=el.dataset.value,id=el.dataset.id;try{if(a==='menu'){const open=$('.main-nav').classList.toggle('open');el.setAttribute('aria-expanded',open)}else if(a==='option'){config[k]=v;updateOptions()}else if(a==='view'){viewMode=v;$('.view-controls').innerHTML=viewButtons();syncPreview()}else if(a==='zoom'){viewMode=viewMode==='detail'?'front':'detail';$('.view-controls').innerHTML=viewButtons();syncPreview()}else if(a==='qty'){config.quantity=Math.min(10000,Math.max(1,Number(config.quantity)+Number(v)));updateOptions()}else if(a==='save-design'){await captureConfigPreview();saveDesign()}else if(a==='to-quote'){await captureConfigPreview();safeSave('kw:config',config);go('quote')}else if(a==='size-guide')sizeModal();else if(a==='close-modal')$('#modal').close();else if(a==='case-modal')openModal(renderCaseModal(id));else if(a==='material-modal')openModal(renderMaterialModal(id));else if(a==='save-draft'){if(safeSave('kw:quote-draft',quoteDraft()))toast(files.length?'입력 내용을 임시 저장했습니다. 첨부 파일은 다시 첨부해 주세요.':'이 브라우저에 입력 내용을 임시 저장했습니다.')}else if(a==='edit-saved'||a==='quote-saved'){const b=brief.find(b=>b.id===id);if(b){config={...b.config};safeSave('kw:config',config);go(a==='edit-saved'?'studio/'+config.product:'quote')}}else if(a==='remove-saved'){brief=brief.filter(b=>b.id!==id);safeSave('kw:brief',brief);render();toast('보관함에서 뺐습니다.')}else if(a==='print-estimate')printDocument(config);else if(a==='print-request'){const r=store.getRequest(id);printDocument(r.configSnapshot,r)}else if(a==='download-json'){const r=store.getRequest(id);downloadBlob(new Blob([JSON.stringify({notice:'LOCAL DEMO — not sent to supplier',request:r},null,2)],{type:'application/json'}),'KUSWEEK-brief-'+id.slice(-8)+'.json')}else if(a==='export-preview'){const blob=await preview.exportPng();downloadBlob(blob,'KUSWEEK-'+config.product+'-'+config.color+'.png');toast('의류 이미지가 저장됩니다. 로고·상세 사양은 요청서에 포함됩니다.')}else if(a==='update-status'){store.updateRequest(id,{status:$('#supplier-status').value});render();toast('데모 진행 상태를 반영했습니다.')}else if(a==='save-supplier-note'){store.updateRequest(id,{supplierNote:$('#supplier-note').value});toast('검토 메모를 저장했습니다.')}else if(a==='open-chat'){chatOpen=true;renderChat();$('#chat-root textarea')?.focus()}else if(a==='close-chat'){chatOpen=false;renderChat()}else if(a==='new-chat'){chatThread=store.createThread({config,title:getProduct(config.product).ko+' 새 상담'}).id;renderChat()}else if(a==='remove-file'){files.splice(Number(el.dataset.index),1);$('#file-list').innerHTML=files.map((f,i)=>`<span class="file-chip">${esc(f.name)} <button type="button" data-action="remove-file" data-index="${i}">×</button></span>`).join('')}else if(a==='attachment'){const f=safeRead('kw:attachments:'+id,[])[Number(el.dataset.index)];if(f){const data=await fetch(f.data).then(r=>r.blob());downloadBlob(data,f.name)}}else if(a==='reset-dialog'){openModal('<h3>이 브라우저의 데모 데이터를 초기화할까요?</h3><p>저장한 디자인, 요청서, 채팅과 첨부가 삭제됩니다. 필요한 요청서는 먼저 내려받아 주세요.</p><div class="actions" style="margin-top:25px"><button class="btn light" data-action="close-modal">취소</button><button class="btn" data-action="confirm-reset">데모 데이터 초기화</button></div>')}else if(a==='confirm-reset'){store.resetDemo();Object.keys(localStorage).filter(k=>k.startsWith('kw:')).forEach(k=>localStorage.removeItem(k));brief=[];config=defaultConfig();chatThread=null;chatOpen=false;$('#modal').close();go('requests');toast('데모 데이터를 초기화했습니다.')}}catch(e){console.error(e);toast('처리하지 못했습니다. '+e.message)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='studio-product'){go('studio/'+el.value)}else if(el.id==='studio-size'){config.size=el.value;safeSave('kw:config',config)}else if(el.id==='studio-quantity'){config.quantity=Math.min(10000,Math.max(1,Math.round(Number(el.value)||1)));el.value=config.quantity;$('#studio-pricing').innerHTML=priceBlock(config);safeSave('kw:config',config)}else if(el.id==='product-sort'){const p=route().params;p.set('sort',el.value);go('products?'+p)}else if(el.id==='size-tbd'){$('#size-fields').hidden=el.checked}else if(el.id==='request-files'){handleFiles(el.files).catch(()=>toast('파일을 읽지 못했습니다.'))}else if(el.id==='fabric-request'){$('#fabric-custom').hidden=el.value!=='직접 입력'}else if(el.id==='auto-reply')store.setAutoReply(el.checked);else if(el.id==='chat-thread'){chatThread=el.value;renderChat()}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='logo-text'){config.logoText=el.value;syncPreview()}if(el.name?.startsWith('size-')){const total=$$('#size-fields input').reduce((s,e)=>s+Number(e.value||0),0);$('#size-total').textContent='사이즈 합계: '+total+'장 / 희망 수량 '+$('#quantity').value+'장'}if(el.id==='quantity'&&$('#quote-pricing'))$('#quote-pricing').innerHTML=priceBlock({...config,quantity:Number(el.value)||1})});
document.addEventListener('submit',event=>{const f=event.target;event.preventDefault();if(f.id==='quote-form')submitQuote(f);else if(f.id==='product-search'){const p=route().params;p.set('q',new FormData(f).get('q'));go('products?'+p)}else if(f.classList.contains('chat-compose')){const input=f.querySelector('textarea'),text=input.value.trim();if(!text)return;input.value='';try{let id=f.dataset.thread;if(!id){id=store.createThread({config,title:getProduct(config.product).ko+' 상담'}).id;chatThread=id}store.sendMessage(id,text,{role:f.dataset.role||'customer'});refreshMessages();renderChat()}catch(e){const current=input.isConnected?input:$('#chat-root textarea');if(current)current.value=text;toast(e.message)}}});
function refreshMessages(){for(const el of $$('.inline-chat')){const box=el.querySelector('.messages');box.innerHTML=messagesHTML(el.dataset.thread,el.dataset.role);box.scrollTop=1e6}}
const requestSignature=state=>JSON.stringify(state.requests.map(r=>[r.id,r.status,r.supplierNote]));
let syncedRequests=requestSignature(store.getState());
function refreshInboxPreservingDraft(previousRequests){const entity=route().parts[0]==='supplier'?inboxId:route().parts[1],active=document.activeElement,key=el=>el.id?'id:'+el.id:(el.closest('[data-thread]')?.dataset.thread||'')+':'+el.tagName+':'+el.name,previous=previousRequests.find(row=>row[0]===entity),fields=$$('#main input,#main textarea,#main select').filter(el=>el===active||(el.id==='supplier-status'?el.value!==previous?.[1]:el.id==='supplier-note'?el.value!==(previous?.[2]||''):true)).map(el=>({key:key(el),value:el.value,checked:el.checked,focused:el===active,start:el.selectionStart,end:el.selectionEnd})),x=window.scrollX,y=window.scrollY,inboxScroll=$('.inbox-list')?.scrollLeft||0;render();const currentRequest=route().parts[0]==='supplier'?store.getRequest(inboxId):null;if(currentRequest){const status=$('#supplier-status'),note=$('#supplier-note');if(status)status.value=currentRequest.status;if(note)note.value=currentRequest.supplierNote||''}const currentEntity=route().parts[0]==='supplier'?inboxId:route().parts[1];if(entity===currentEntity){for(const saved of fields){const el=$$('#main input,#main textarea,#main select').find(item=>key(item)===saved.key);if(!el)continue;el.value=saved.value;if(typeof saved.checked==='boolean')el.checked=saved.checked;if(saved.focused){el.focus({preventScroll:true});if(typeof saved.start==='number'&&typeof el.setSelectionRange==='function')try{el.setSelectionRange(saved.start,saved.end)}catch{}}}}if($('.inbox-list'))$('.inbox-list').scrollLeft=inboxScroll;window.scrollTo({left:x,top:y,behavior:'instant'})}
store.subscribe(state=>{const next=requestSignature(state),requestsChanged=next!==syncedRequests,previousRequests=requestsChanged?JSON.parse(syncedRequests):[];syncedRequests=next;if(rendering)return;const {parts:[page,id]}=route();if(requestsChanged&&(page==='supplier'||page==='requests')){refreshInboxPreservingDraft(previousRequests);return}refreshMessages();renderChat();if(page==='requests'&&id){const r=store.getRequest(id),track=$('.status-track');if(track&&r){track.outerHTML=statusTrack(r.status);const badge=$('main .badge');if(badge)badge.textContent=statusLabels[r.status]}}},{immediate:false});
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render()});
window.addEventListener('storage',e=>{if(e.key==='kw:brief'){brief=safeRead('kw:brief',[]);$$('.bag-count').forEach(x=>x.textContent=brief.length)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
document.addEventListener('click',event=>{if(event.target.closest('.skip')){event.preventDefault();const main=$('#main');main.tabIndex=-1;main.focus();main.scrollIntoView({block:'start'})}},true);
let dragStart=null;
document.addEventListener('pointerdown',event=>{if(event.target.closest('.garment-canvas')&&config.product==='field')dragStart={x:event.clientX,y:event.clientY}});
document.addEventListener('pointerup',event=>{if(!dragStart)return;const dx=event.clientX-dragStart.x,dy=event.clientY-dragStart.y;dragStart=null;if(Math.abs(dx)<40||Math.abs(dx)<Math.abs(dy))return;const views=['front','angle','side','back'],index=Math.max(0,views.indexOf(viewMode));viewMode=views[(index+(dx<0?1:3))%4];config.view=viewMode;if($('.view-controls'))$('.view-controls').innerHTML=viewButtons();syncPreview()});
render();

